@app.route('/api/admin/ping-google', methods=['POST'])
@admin_required
def ping_google():
    try:
        import requests
        sitemap_url = 'https://novabrief-web.onrender.com/sitemap.xml'
        google_ping_url = f'https://www.google.com/ping?sitemap={sitemap_url}'
        response = requests.get(google_ping_url, timeout=10)
        return jsonify({'status': 'success', 'message': f'Google ping response code: {response.status_code}'})
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 500


@app.after_request
def add_security_headers(response):
    response.headers['X-Content-Type-Options'] = 'nosniff'
    response.headers['X-Frame-Options'] = 'SAMEORIGIN'
    response.headers['X-XSS-Protection'] = '1; mode=block'
    return response


@app.route('/user/forgot-password', methods=['GET', 'POST'])
def forgot_password():
    if request.method == 'GET':
        return render_template('forgot_password.html')
    
    email = request.form.get('email', '').strip().lower()
    user = db.get_user_by_email(email)
    
    if user:
        import uuid
        from datetime import timedelta
        token = str(uuid.uuid4())
        expiry = (datetime.now() + timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S')
        db.set_password_reset_token(email, token, expiry)
        
        try:
            from ai_news_agent import send_password_reset_email
            threading.Thread(target=send_password_reset_email, args=(email, token), daemon=True).start()
        except Exception as e:
            logger.error(f'Could not send reset email: {e}')
            
    # Always return success message to prevent email enumeration
    return render_template('forgot_password.html', success=True)

@app.route('/user/reset-password/<token>', methods=['GET', 'POST'])
def reset_password(token):
    if request.method == 'GET':
        return render_template('reset_password.html', token=token)
        
    password = request.form.get('password')
    if not password or len(password) < 6:
        return render_template('reset_password.html', token=token, error="Password must be at least 6 characters.")
        
    new_hash = generate_password_hash(password)
    success = db.verify_and_clear_reset_token(token, new_hash)
    
    if success:
        return redirect(url_for('user_login_page', message="Password updated successfully! You can now log in."))
    else:
        return render_template('reset_password.html', token=token, error="Invalid or expired reset link. Please try again.")

@app.errorhandler(404)
def not_found(e):
    if request.path.startswith('/api/'):
        return jsonify({'error': 'Resource not found'}), 404
    return render_template('index.html'), 404

@app.errorhandler(500)
def server_error(e):
    logger.error(f'Server error: {e}')
    if request.path.startswith('/api/'):
        return jsonify({'error': 'Internal server error'}), 500
    return render_template('500.html'), 500


# -- Blog Routes ---------------------------------------------------------------

@app.route('/blog')
def blog_index():
    import psycopg2
    import psycopg2.extras
    import os
    conn = psycopg2.connect(os.getenv('DATABASE_URL'))
    cursor = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        cursor.execute("SELECT * FROM blog_posts ORDER BY published_at DESC")
        posts = [dict(row) for row in cursor.fetchall()]
    except Exception:
        posts = []
    conn.close()
    return render_template('blog_list.html', posts=posts)

@app.route('/blog/<slug>')
def blog_post(slug):
    import psycopg2
    import psycopg2.extras
    import os
    conn = psycopg2.connect(os.getenv('DATABASE_URL'))
    cursor = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    try:
        cursor.execute("SELECT * FROM blog_posts WHERE slug=%s", (slug,))
        row = cursor.fetchone()
    except Exception:
        row = None
    conn.close()
    if not row:
        return "Post not found", 404
    return render_template('blog_post.html', post=dict(row))


# -- Background Scheduler -----------------------------------------------------

_scheduler_started = False

def _safe_run_news_digest():
    try:
        from ai_news_agent import run_news_digest
        run_news_digest()
    except Exception as e:
        logger.error(f'Scheduled news digest failed: {e}')

def _safe_fetch_hourly():
    try:
        from ai_news_agent import fetch_latest_news_hourly
        fetch_latest_news_hourly()
    except Exception as e:
        logger.error(f'Scheduled hourly fetch failed: {e}')

def _safe_send_program_notifications():
    try:
        from ai_news_agent import send_program_notifications
        send_program_notifications()
    except Exception as e:
        logger.error(f'Scheduled program notifications failed: {e}')

def start_background_scheduler():
    global _scheduler_started
    if _scheduler_started:
        return
    _scheduler_started = True
    try:
        from apscheduler.schedulers.background import BackgroundScheduler
        scheduler = BackgroundScheduler(daemon=True)
        scheduler.add_job(
            _safe_fetch_hourly, 'cron', minute=0,
            id='hourly_news_fetch', replace_existing=True, misfire_grace_time=1800
        )
        scheduler.add_job(
            _safe_run_news_digest, 'cron', hour=10, minute=0,
            id='daily_news_digest', replace_existing=True, misfire_grace_time=3600
        )
        scheduler.add_job(
            _safe_send_program_notifications, 'cron', hour=10, minute=0,
            id='daily_program_check', replace_existing=True, misfire_grace_time=3600
        )
        scheduler.start()
        logger.info('Scheduler started: News digest 10:00 AM UTC (3 PM PKT), Program notifications 10:00 AM UTC (3 PM PKT).')
    except Exception as e:
        logger.error(f'Could not start background scheduler: {e}')

start_background_scheduler()


